function calculateSpecificity(selector) {
  let a = 0, b = 0, c = 0;

  selector = selector.replace(/:not\(([^)]*)\)/g, '$1');
  const parts = selector.trim().split(/[\s>+~]+/);

  for (let part of parts) {
    if (!part || part === '*') continue;

    const ids = part.match(/#[\w-]+/g) || [];
    a += ids.length;

    const classes = part.match(/\.[\w-]+/g) || [];
    const attrs = part.match(/\[[^\]]*\]/g) || [];
    const pseudoClasses = part.match(/:[a-zA-Z][\w-]*/g) || [];
    b += classes.length + attrs.length + pseudoClasses.length;

    const pseudoElements = part.match(/::[\w-]+/g) || [];
    c += pseudoElements.length;

    let clean = part.replace(/#[\w-]+/g, '')
                     .replace(/\.[\w-]+/g, '')
                     .replace(/\[[^\]]*\]/g, '')
                     .replace(/::[\w-]+/g, '')
                     .replace(/:[\w-]+/g, '');
    if (clean && clean !== '*') c += 1;
  }

  return [a, b, c];
}

function compareSpecificity(sel1, sel2) {
  const s1 = calculateSpecificity(sel1);
  const s2 = calculateSpecificity(sel2);
  for (let i = 0; i < 3; i++) {
    if (s1[i] > s2[i]) return 1;
    if (s1[i] < s2[i]) return -1;
  }
  return 0;
}
